<?php
require_once __DIR__ . '/_layout.php'; requirePermission('pricing.manage');
$ids=currentAgencyIds();if(!$ids)$ids=[0];$ph=implode(',',array_fill(0,count($ids),'?'));$rules=dbFetchAll("SELECT pr.*,a.name agency_name,vc.name category_name FROM pricing_rules pr JOIN agencies a ON a.id=pr.agency_id LEFT JOIN vehicle_categories vc ON vc.id=pr.category_id WHERE pr.agency_id IN ($ph) AND pr.archived_at IS NULL ORDER BY pr.priority,pr.name",$ids);backofficeHeader(t('nav.pricing'),'pricing.php');?><?php pageHeader('page.pricing.title', 'page.pricing.description', ['breadcrumbs'=>[['label'=>'nav.commercial'],['label'=>'nav.pricing']],'primary'=>['label'=>'action.create_rule','href'=>'pricing_form.php']]); ?><div class="grid"><section class="card full"><div class="section-card-header"><h2><?=navigationIcon('commercial')?><?=e(t('section.pricing_rules'))?></h2></div><div class="table-wrap"><table><tr><th><?=e(t('field.agency'))?></th><th><?=e(t('field.name'))?></th><th><?=e(t('field.type'))?></th><th><?=e(t('field.category'))?></th><th><?=e(t('field.adjustment'))?></th><th><?=e(t('field.period'))?></th><th><?=e(t('common.status'))?></th></tr><?php foreach($rules as $r):?><tr><td><?=e($r['agency_name'])?></td><td><?=e($r['name'])?></td><td><?=e(t('option.'.$r['rule_type']))?></td><td><?=e($r['category_name']?:t('common.all'))?></td><td><bdi><?=e(t('option.'.$r['adjustment_type']).' '.$r['adjustment_value'])?></bdi></td><td><?=formattedDateTime($r['starts_at'])?><br><?=formattedDateTime($r['ends_at'])?></td><td><?=statusBadge($r['status'])?></td></tr><?php endforeach;?></table><?php if(!$rules)echo emptyState('empty.no_records');?></div></section></div><?php backofficeFooter();
